(3798296, 534583, 66353, '<td valign="top">I think this would have worked better on another kind of surface - and I think I would prefer it in color too (but that would probably make the floor look even worse). Besides that it''s an interesting take on the challenge.</td>', 'I think this would have worked better on another kind of surface - and I think I would prefer it in color too (but that would probably make the floor look even worse). Besides that it''s an interesting take on the challenge.', '2007-06-18 15:24:43.000000', NULL, 1),
(3798304, 537733, 66353, '<td valign="top">A little over processed for my taste - besides that I like it.</td>', 'A little over processed for my taste - besides that I like it.', '2007-06-18 15:26:50.000000', NULL, 1),
(3798307, 533751, 66353, '<td valign="top">That''s very good - and a different take on the challenge :)</td>', 'That''s very good - and a different take on the challenge :)', '2007-06-18 15:27:48.000000', NULL, 1),
(3798313, 537578, 66353, '<td valign="top">Original and creative. I like it...</td>', 'Original and creative. I like it...', '2007-06-18 15:28:36.000000', NULL, 1),
(3798316, 538218, 66353, '<td valign="top">Great colors and composition.</td>', 'Great colors and composition.', '2007-06-18 15:29:05.000000', NULL, 1),
(3798317, 538027, 66353, '<td valign="top">Nice action shot.</td>', 'Nice action shot.', '2007-06-18 15:29:10.000000', NULL, 1),
