(3802432, 535911, 811, '<td valign="top">Hahahha -- too funny.</td>', 'Hahahha -- too funny.', '2007-06-19 16:43:18.000000', NULL, 1),
(3802433, 536492, 811, '<td valign="top">A very soft, sweet moment.  Great shot.</td>', 'A very soft, sweet moment.  Great shot.', '2007-06-19 16:43:30.000000', NULL, 1),
